import{_ as a,o as t,c as n,a3 as e}from"./chunks/framework.Zs2ruvLs.js";const d=JSON.parse('{"title":"Arbitrary Value Unit (AVU) Energy Oracle","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/avu-energy-oracle.md","filePath":"architecture/avu-energy-oracle.md","lastUpdated":1791664145000}'),p={name:"architecture/avu-energy-oracle.md"};function l(m,s,i,r,c,o){return t(),n("div",null,[...s[0]||(s[0]=[e('<h1 id="arbitrary-value-unit-avu-energy-oracle" tabindex="-1">Arbitrary Value Unit (AVU) Energy Oracle <a class="header-anchor" href="#arbitrary-value-unit-avu-energy-oracle" aria-label="Permalink to &quot;Arbitrary Value Unit (AVU) Energy Oracle&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Frank eliminates fiat currencies (such as the US Dollar) from core wallet interfaces, atomic swaps, and token comparisons. In their place, Frank uses the <strong>Arbitrary Value Unit (AVU)</strong>:</p><div class="katex-display"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mn>1</mn><mtext> AVU</mtext><mo>≡</mo><mn>1</mn><mtext> Kilowatt-Hour (kWh)</mtext><mo>=</mo><mn>3.6</mn><mo>×</mo><msup><mn>10</mn><mn>6</mn></msup><mtext> Joules</mtext></mrow><annotation encoding="application/x-tex">1\\text{ AVU} \\equiv 1\\text{ Kilowatt-Hour (kWh)} = 3.6\\times 10^6\\text{ Joules} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">1</span><span class="mord text"><span class="mord"> AVU</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≡</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">1</span><span class="mord text"><span class="mord"> Kilowatt-Hour (kWh)</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">3.6</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8641em;"></span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8641em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">6</span></span></span></span></span></span></span></span><span class="mord text"><span class="mord"> Joules</span></span></span></span></span></span></div><p>Every token, asset, and wallet balance is measured directly in the physical energy (kWh) it commands.</p><hr><h2 id="why-the-avu-is-valuable" tabindex="-1">Why the AVU is Valuable <a class="header-anchor" href="#why-the-avu-is-valuable" aria-label="Permalink to &quot;Why the AVU is Valuable&quot;">​</a></h2><h3 id="the-oracle-less-paradigm" tabindex="-1">The &quot;Oracle-less&quot; Paradigm <a class="header-anchor" href="#the-oracle-less-paradigm" aria-label="Permalink to &quot;The &quot;Oracle-less&quot; Paradigm&quot;">​</a></h3><p>Traditional financial applications rely on centralized or federated price oracles (Chainlink, Pyth, Bloomberg, central exchange orderbooks, or commodity brokers). These introduce:</p><ul><li>Relayer collusion and bridge exploit vectors.</li><li>Fragility during extreme market volatility.</li><li>Jurisdictional regulatory attack vectors.</li></ul><p>In contrast, <strong>Proof-of-Work thermodynamic consensus is inherently oracle-less</strong>:</p><ul><li><strong>Hashrate, Difficulty, and Subsidy Schedules</strong> are baked directly into consensus rules and verified independently by full nodes.</li><li>The physical cost of mining cannot be faked or printed. It is governed by the laws of physics: electricity, transistor switching, and thermal dissipation.</li><li>Millions of independent mining operators globally arbitrage electricity down to its marginal thermodynamic cost, transforming the global ASIC fleet into an unbribable, decentralized sensor of the real-world value of energy.</li></ul><h3 id="energy-at-the-base-of-every-single-supply-chain" tabindex="-1">Energy: At the Base of Every Single Supply Chain <a class="header-anchor" href="#energy-at-the-base-of-every-single-supply-chain" aria-label="Permalink to &quot;Energy: At the Base of Every Single Supply Chain&quot;">​</a></h3><p>Thermodynamically, <strong>every physical good and human service is organized energy</strong>:</p><ul><li><strong>Food</strong>: Natural gas synthesis into ammonia fertilizer (Haber-Bosch) + diesel machinery + solar irradiance + refrigerated logistical chains.</li><li><strong>Semiconductors</strong>: High-purity monocrystalline silicon refined at thousands of degrees + extreme ultraviolet (EUV) lithography lasers consuming hundreds of kilowatts each.</li><li><strong>Fresh Water</strong>: Energy required for reverse-osmosis desalination, deep aquifer pumping, and urban transport.</li><li><strong>Shelter</strong>: Calcination of limestone into cement (<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1</mn><mo separator="true">,</mo><msup><mn>450</mn><mo>∘</mo></msup><mtext>C</mtext></mrow><annotation encoding="application/x-tex">1,450^\\circ\\text{C}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord">1</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">45</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6741em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mbin mtight">∘</span></span></span></span></span></span></span></span><span class="mord text"><span class="mord">C</span></span></span></span></span>) + blast furnace steel reduction.</li><li><strong>Compute &amp; AI</strong>: Terawatt-hours consumed by tensor processing units, cooling chillers, and data infrastructure.</li></ul><p>Energy is the fundamental invariant cost input of the global economy. By pricing assets in <strong>AVU (<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1</mn><mtext> kWh</mtext></mrow><annotation encoding="application/x-tex">1\\text{ kWh}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord">1</span><span class="mord text"><span class="mord"> kWh</span></span></span></span></span>)</strong>, purchasing power is measured against the root denominator of physical reality.</p><h3 id="refusing-the-usd-meme-weakening-the-fed-s-psychological-hold" tabindex="-1">Refusing the USD Meme: Weakening the Fed&#39;s Psychological Hold <a class="header-anchor" href="#refusing-the-usd-meme-weakening-the-fed-s-psychological-hold" aria-label="Permalink to &quot;Refusing the USD Meme: Weakening the Fed&#39;s Psychological Hold&quot;">​</a></h3><p>Money is fundamentally the most pervasive coordination meme in human society. For nearly a century, software interfaces, spreadsheet programs, and banking applications have unquestioningly defaulted to the US Dollar as the universal unit of account. This ubiquitous visual conditioning creates a powerful psychological illusion: the belief that the Dollar is an objective baseline, while the real world &quot;fluctuates.&quot;</p><p>In truth, the Federal Reserve can dilute the dollar supply with arbitrary ledger entries, yet software continues to render that diluted denominator as the immutable ground truth.</p><p><strong>Frank explicitly rejects the USD meme.</strong> By deliberately stripping fiat currency display from the wallet interface and replacing it with physical kilowatt-hours (AVU):</p><ol><li><strong>It breaks the psychological monopoly of the Fed</strong>: Users are no longer conditioned to evaluate their life energy and savings in units decreed by central planners.</li><li><strong>It deflates the currency meme</strong>: A meme only retains power as long as participants repeat and display it. Denying fiat real estate in self-custodial software directly weakens its social network effect.</li><li><strong>It aligns perception with thermodynamics</strong>: The user&#39;s wealth is presented in terms of invariant physical work (<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>3.6</mn><mo>×</mo><msup><mn>10</mn><mn>6</mn></msup><mtext> Joules</mtext></mrow><annotation encoding="application/x-tex">3.6 \\times 10^6 \\text{ Joules}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">3.6</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">6</span></span></span></span></span></span></span></span><span class="mord text"><span class="mord"> Joules</span></span></span></span></span>), where no committee or algorithm can print more energy out of thin air.</li></ol><hr><h2 id="bypassing-the-cpi-exposing-the-true-debasement-of-usd" tabindex="-1">Bypassing the CPI &amp; Exposing the True Debasement of USD <a class="header-anchor" href="#bypassing-the-cpi-exposing-the-true-debasement-of-usd" aria-label="Permalink to &quot;Bypassing the CPI &amp; Exposing the True Debasement of USD&quot;">​</a></h2><h3 id="the-flaws-of-the-consumer-price-index-cpi" tabindex="-1">The Flaws of the Consumer Price Index (CPI) <a class="header-anchor" href="#the-flaws-of-the-consumer-price-index-cpi" aria-label="Permalink to &quot;The Flaws of the Consumer Price Index (CPI)&quot;">​</a></h3><p>For decades, official government inflation metrics—predominantly the Consumer Price Index (CPI)—have obscured currency debasement through statistical engineering:</p><ol><li><strong>Substitution Bias</strong>: Assumes consumers substitute down to lower-grade alternatives when prime goods surge in price.</li><li><strong>Hedonic Adjustments</strong>: Artificially subtracts subjective &quot;quality improvements&quot; from sticker price hikes.</li><li><strong>Exclusion of Capital Goods &amp; Assets</strong>: Omits real estate, farmland, and equities—the primary sinks where newly created fiat accumulates.</li></ol><h3 id="tracking-the-real-worth-of-the-dollar-over-time" tabindex="-1">Tracking the Real Worth of the Dollar Over Time <a class="header-anchor" href="#tracking-the-real-worth-of-the-dollar-over-time" aria-label="Permalink to &quot;Tracking the Real Worth of the Dollar Over Time&quot;">​</a></h3><p>Because the face value of a dollar bill remains stamped &quot;$1.00&quot;, the public perceives prices as &quot;mysteriously rising,&quot; when in fact <strong>the currency measuring stick is shrinking</strong>.</p><p>Anchoring to <strong><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1</mn><mtext> AVU</mtext><mo>≡</mo><mn>1</mn><mtext> kWh</mtext></mrow><annotation encoding="application/x-tex">1\\text{ AVU} \\equiv 1\\text{ kWh}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">1</span><span class="mord text"><span class="mord"> AVU</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≡</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord">1</span><span class="mord text"><span class="mord"> kWh</span></span></span></span></span></strong> lays bare the real worth of the dollar across decadal horizons:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Era</th><th style="text-align:left;">US Industrial Electricity Cost</th><th style="text-align:left;"><strong>kWh of Energy Purchased per $1.00</strong></th><th style="text-align:left;">Dollar Purchasing Power in AVU</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>1930s</strong></td><td style="text-align:left;"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>≈</mo><mi mathvariant="normal">$</mi><mn>0.007</mn><mi mathvariant="normal">/</mi><mtext>kWh</mtext></mrow><annotation encoding="application/x-tex">\\approx \\$0.007 / \\text{kWh}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4831em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">$0.007/</span><span class="mord text"><span class="mord">kWh</span></span></span></span></span></td><td style="text-align:left;"><strong><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>142.8</mn><mtext> kWh / $</mtext></mrow><annotation encoding="application/x-tex">142.8\\text{ kWh / \\$}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">142.8</span><span class="mord text"><span class="mord"> kWh / $</span></span></span></span></span></strong></td><td style="text-align:left;"><strong><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>142.8</mn><mtext> AVU / $</mtext></mrow><annotation encoding="application/x-tex">142.8\\text{ AVU / \\$}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">142.8</span><span class="mord text"><span class="mord"> AVU / $</span></span></span></span></span></strong></td></tr><tr><td style="text-align:left;"><strong>1970</strong></td><td style="text-align:left;"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>≈</mo><mi mathvariant="normal">$</mi><mn>0.010</mn><mi mathvariant="normal">/</mi><mtext>kWh</mtext></mrow><annotation encoding="application/x-tex">\\approx \\$0.010 / \\text{kWh}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4831em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">$0.010/</span><span class="mord text"><span class="mord">kWh</span></span></span></span></span></td><td style="text-align:left;"><strong><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>100.0</mn><mtext> kWh / $</mtext></mrow><annotation encoding="application/x-tex">100.0\\text{ kWh / \\$}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">100.0</span><span class="mord text"><span class="mord"> kWh / $</span></span></span></span></span></strong></td><td style="text-align:left;"><strong><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>100.0</mn><mtext> AVU / $</mtext></mrow><annotation encoding="application/x-tex">100.0\\text{ AVU / \\$}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">100.0</span><span class="mord text"><span class="mord"> AVU / $</span></span></span></span></span></strong></td></tr><tr><td style="text-align:left;"><strong>2000</strong></td><td style="text-align:left;"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>≈</mo><mi mathvariant="normal">$</mi><mn>0.045</mn><mi mathvariant="normal">/</mi><mtext>kWh</mtext></mrow><annotation encoding="application/x-tex">\\approx \\$0.045 / \\text{kWh}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4831em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">$0.045/</span><span class="mord text"><span class="mord">kWh</span></span></span></span></span></td><td style="text-align:left;"><strong><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>22.2</mn><mtext> kWh / $</mtext></mrow><annotation encoding="application/x-tex">22.2\\text{ kWh / \\$}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">22.2</span><span class="mord text"><span class="mord"> kWh / $</span></span></span></span></span></strong></td><td style="text-align:left;"><strong><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>22.2</mn><mtext> AVU / $</mtext></mrow><annotation encoding="application/x-tex">22.2\\text{ AVU / \\$}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">22.2</span><span class="mord text"><span class="mord"> AVU / $</span></span></span></span></span></strong></td></tr><tr><td style="text-align:left;"><strong>2026 (Present)</strong></td><td style="text-align:left;"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>≈</mo><mi mathvariant="normal">$</mi><mn>0.084</mn><mi mathvariant="normal">/</mi><mtext>kWh</mtext></mrow><annotation encoding="application/x-tex">\\approx \\$0.084 / \\text{kWh}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4831em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">$0.084/</span><span class="mord text"><span class="mord">kWh</span></span></span></span></span></td><td style="text-align:left;"><strong><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>11.9</mn><mtext> kWh / $</mtext></mrow><annotation encoding="application/x-tex">11.9\\text{ kWh / \\$}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">11.9</span><span class="mord text"><span class="mord"> kWh / $</span></span></span></span></span></strong></td><td style="text-align:left;"><strong><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>11.9</mn><mtext> AVU / $</mtext></mrow><annotation encoding="application/x-tex">11.9\\text{ AVU / \\$}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">11.9</span><span class="mord text"><span class="mord"> AVU / $</span></span></span></span></span></strong></td></tr></tbody></table><p>Over the past century, the US Dollar has lost <strong><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>&gt;</mo><mn>91</mn><mi mathvariant="normal">%</mi></mrow><annotation encoding="application/x-tex">&gt; 91\\%</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5782em;vertical-align:-0.0391em;"></span><span class="mrel">&gt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8056em;vertical-align:-0.0556em;"></span><span class="mord">91%</span></span></span></span> of its energy purchasing power</strong>. Tracking <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mtext>AVU/$</mtext></mrow><annotation encoding="application/x-tex">\\text{AVU/\\$}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord text"><span class="mord">AVU/$</span></span></span></span></span> over time provides an unforgeable, physical record of monetary inflation free of bureaucratic revisions.</p><hr><h2 id="the-pow-thermodynamic-derivation" tabindex="-1">The PoW Thermodynamic Derivation <a class="header-anchor" href="#the-pow-thermodynamic-derivation" aria-label="Permalink to &quot;The PoW Thermodynamic Derivation&quot;">​</a></h2><p>Under competitive Proof-of-Work mining markets:</p><div class="katex-display"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mtext>Network Energy Cost</mtext><mo>=</mo><mfrac><mrow><mtext>Spot Price </mtext><mo stretchy="false">[</mo><mi mathvariant="normal">$</mi><mo stretchy="false">]</mo><mo>×</mo><mtext>Reward Rate </mtext><mo stretchy="false">[</mo><mtext>coins/sec</mtext><mo stretchy="false">]</mo></mrow><mrow><mtext>Hashrate </mtext><mo stretchy="false">[</mo><mtext>H/s</mtext><mo stretchy="false">]</mo><mo>×</mo><mtext>Electricity per Hash </mtext><mo stretchy="false">[</mo><mtext>kWh/H</mtext><mo stretchy="false">]</mo></mrow></mfrac><mo>=</mo><mrow><mo fence="true">[</mo><mfrac><mi mathvariant="bold">$</mi><mtext>kWh</mtext></mfrac><mo fence="true">]</mo></mrow></mrow><annotation encoding="application/x-tex">\\text{Network Energy Cost} = \\frac{\\text{Spot Price } [\\$] \\times \\text{Reward Rate } [\\text{coins/sec}]}{\\text{Hashrate } [\\text{H/s}] \\times \\text{Electricity per Hash } [\\text{kWh/H}]} = \\mathbf{\\left[\\frac{\\$}{\\text{kWh}}\\right]} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord text"><span class="mord">Network Energy Cost</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.363em;vertical-align:-0.936em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.427em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord text"><span class="mord">Hashrate </span></span><span class="mopen">[</span><span class="mord text"><span class="mord">H/s</span></span><span class="mclose">]</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord text"><span class="mord">Electricity per Hash </span></span><span class="mopen">[</span><span class="mord text"><span class="mord">kWh/H</span></span><span class="mclose">]</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord text"><span class="mord">Spot Price </span></span><span class="mopen">[</span><span class="mord">$</span><span class="mclose">]</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord text"><span class="mord">Reward Rate </span></span><span class="mopen">[</span><span class="mord text"><span class="mord">coins/sec</span></span><span class="mclose">]</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.936em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.4em;vertical-align:-0.95em;"></span><span class="minner"><span class="mopen delimcenter" style="top:0em;"><span class="delimsizing size3">[</span></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.427em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord text"><span class="mord">kWh</span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathbf">$</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mclose delimcenter" style="top:0em;"><span class="delimsizing size3">]</span></span></span></span></span></span></span></div><p>Inverting this cost gives the <strong>AVU conversion multiplier</strong>:</p><div class="katex-display"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mtext>Conversion Multiplier</mtext><mo>=</mo><mfrac><mn>1</mn><mtext>Network Energy Cost</mtext></mfrac><mo>=</mo><mrow><mo fence="true">[</mo><mfrac><mtext>kWh</mtext><mi mathvariant="bold">$</mi></mfrac><mo fence="true">]</mo></mrow><mo>≡</mo><mrow><mo fence="true">[</mo><mfrac><mtext>AVU</mtext><mi mathvariant="bold">$</mi></mfrac><mo fence="true">]</mo></mrow></mrow><annotation encoding="application/x-tex">\\text{Conversion Multiplier} = \\frac{1}{\\text{Network Energy Cost}} = \\mathbf{\\left[\\frac{\\text{kWh}}{\\$}\\right]} \\equiv \\mathbf{\\left[\\frac{\\text{AVU}}{\\$}\\right]} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord text"><span class="mord">Conversion Multiplier</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.2019em;vertical-align:-0.8804em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3214em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord text"><span class="mord">Network Energy Cost</span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.8804em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.4em;vertical-align:-0.95em;"></span><span class="minner"><span class="mopen delimcenter" style="top:0em;"><span class="delimsizing size3">[</span></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3714em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathbf">$</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord text"><span class="mord">kWh</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.7416em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mclose delimcenter" style="top:0em;"><span class="delimsizing size3">]</span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≡</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.4em;vertical-align:-0.95em;"></span><span class="minner"><span class="mopen delimcenter" style="top:0em;"><span class="delimsizing size3">[</span></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3603em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathbf">$</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord text"><span class="mord">AVU</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.7416em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mclose delimcenter" style="top:0em;"><span class="delimsizing size3">]</span></span></span></span></span></span></span></div><h3 id="pricing-assets-in-avu" tabindex="-1">Pricing Assets in AVU <a class="header-anchor" href="#pricing-assets-in-avu" aria-label="Permalink to &quot;Pricing Assets in AVU&quot;">​</a></h3><p>For any asset with price <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>P</mi><mtext>asset</mtext></msub></mrow><annotation encoding="application/x-tex">P_{\\text{asset}}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">asset</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>:</p><div class="katex-display"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mtext>Asset AVU</mtext><mo>=</mo><msub><mi>P</mi><mtext>asset</mtext></msub><mrow><mo fence="true">[</mo><mfrac><mi mathvariant="normal">$</mi><mtext>token</mtext></mfrac><mo fence="true">]</mo></mrow><mo>×</mo><mtext>Conversion Multiplier</mtext><mrow><mo fence="true">[</mo><mfrac><mtext>AVU</mtext><mi mathvariant="normal">$</mi></mfrac><mo fence="true">]</mo></mrow><mo>=</mo><mrow><mo fence="true">[</mo><mfrac><mtext>AVU</mtext><mtext>token</mtext></mfrac><mo fence="true">]</mo></mrow></mrow><annotation encoding="application/x-tex">\\text{Asset AVU} = P_{\\text{asset}} \\left[\\frac{\\$}{\\text{token}}\\right] \\times \\text{Conversion Multiplier} \\left[\\frac{\\text{AVU}}{\\$}\\right] = \\mathbf{\\left[\\frac{\\text{AVU}}{\\text{token}}\\right]} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord text"><span class="mord">Asset AVU</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.4em;vertical-align:-0.95em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">asset</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner"><span class="mopen delimcenter" style="top:0em;"><span class="delimsizing size3">[</span></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.427em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord text"><span class="mord">token</span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">$</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mclose delimcenter" style="top:0em;"><span class="delimsizing size3">]</span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:2.4em;vertical-align:-0.95em;"></span><span class="mord text"><span class="mord">Conversion Multiplier</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner"><span class="mopen delimcenter" style="top:0em;"><span class="delimsizing size3">[</span></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3603em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">$</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord text"><span class="mord">AVU</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.7416em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mclose delimcenter" style="top:0em;"><span class="delimsizing size3">]</span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.4em;vertical-align:-0.95em;"></span><span class="minner"><span class="mopen delimcenter" style="top:0em;"><span class="delimsizing size3">[</span></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3603em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord text"><span class="mord">token</span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord text"><span class="mord">AVU</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mclose delimcenter" style="top:0em;"><span class="delimsizing size3">]</span></span></span></span></span></span></span></div><p>The quotation currency (<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi mathvariant="normal">$</mi></mrow><annotation encoding="application/x-tex">\\$</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8056em;vertical-align:-0.0556em;"></span><span class="mord">$</span></span></span></span>) completely cancels out.</p><hr><h2 id="empirical-benchmark-multi-chain-weights" tabindex="-1">Empirical Benchmark &amp; Multi-Chain Weights <a class="header-anchor" href="#empirical-benchmark-multi-chain-weights" aria-label="Permalink to &quot;Empirical Benchmark &amp; Multi-Chain Weights&quot;">​</a></h2><p>Across the top mined networks, the empirical cost of electricity matches the real-world industrial grid:</p><ul><li><strong>Bitcoin (BTC)</strong>: <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>≈</mo><mi mathvariant="normal">$</mi><mn>0.0840</mn><mtext> / kWh</mtext></mrow><annotation encoding="application/x-tex">\\approx \\$0.0840\\text{ / kWh}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4831em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">$0.0840</span><span class="mord text"><span class="mord"> / kWh</span></span></span></span></span> (<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>11.90</mn><mtext> AVU / $</mtext></mrow><annotation encoding="application/x-tex">11.90\\text{ AVU / \\$}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">11.90</span><span class="mord text"><span class="mord"> AVU / $</span></span></span></span></span>)</li><li><strong>Bitcoin Cash (BCH)</strong>: <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>≈</mo><mi mathvariant="normal">$</mi><mn>0.1150</mn><mtext> / kWh</mtext></mrow><annotation encoding="application/x-tex">\\approx \\$0.1150\\text{ / kWh}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4831em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">$0.1150</span><span class="mord text"><span class="mord"> / kWh</span></span></span></span></span> (<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>8.70</mn><mtext> AVU / $</mtext></mrow><annotation encoding="application/x-tex">8.70\\text{ AVU / \\$}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">8.70</span><span class="mord text"><span class="mord"> AVU / $</span></span></span></span></span>)</li><li><strong>eCash (XEC)</strong> <em>(Net to Miner)</em>: <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>≈</mo><mi mathvariant="normal">$</mi><mn>0.1413</mn><mtext> / kWh</mtext></mrow><annotation encoding="application/x-tex">\\approx \\$0.1413\\text{ / kWh}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4831em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">$0.1413</span><span class="mord text"><span class="mord"> / kWh</span></span></span></span></span> (<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>7.08</mn><mtext> AVU / $</mtext></mrow><annotation encoding="application/x-tex">7.08\\text{ AVU / \\$}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">7.08</span><span class="mord text"><span class="mord"> AVU / $</span></span></span></span></span>)</li><li><strong>Merged Scrypt (LTC + DOGE)</strong>: <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>≈</mo><mi mathvariant="normal">$</mi><mn>0.0394</mn><mtext> / kWh</mtext></mrow><annotation encoding="application/x-tex">\\approx \\$0.0394\\text{ / kWh}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4831em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">$0.0394</span><span class="mord text"><span class="mord"> / kWh</span></span></span></span></span> (<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>25.38</mn><mtext> AVU / $</mtext></mrow><annotation encoding="application/x-tex">25.38\\text{ AVU / \\$}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">25.38</span><span class="mord text"><span class="mord"> AVU / $</span></span></span></span></span>)</li><li><strong>Kaspa (KAS)</strong>: <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>≈</mo><mi mathvariant="normal">$</mi><mn>0.0595</mn><mtext> / kWh</mtext></mrow><annotation encoding="application/x-tex">\\approx \\$0.0595\\text{ / kWh}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4831em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">$0.0595</span><span class="mord text"><span class="mord"> / kWh</span></span></span></span></span> (<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>16.81</mn><mtext> AVU / $</mtext></mrow><annotation encoding="application/x-tex">16.81\\text{ AVU / \\$}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">16.81</span><span class="mord text"><span class="mord"> AVU / $</span></span></span></span></span>)</li></ul><h3 id="composite-benchmark" tabindex="-1">Composite Benchmark <a class="header-anchor" href="#composite-benchmark" aria-label="Permalink to &quot;Composite Benchmark&quot;">​</a></h3><p>Frank uses a composite multi-chain Proof-of-Work energy benchmark:</p><div class="katex-display"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mover accent="true"><mrow><mi mathvariant="normal">$</mi><mi mathvariant="normal">/</mi><mtext>kWh</mtext></mrow><mo stretchy="true">‾</mo></mover><mo>≈</mo><mrow><mi mathvariant="bold">$</mi><mn mathvariant="bold">0.084</mn><mi mathvariant="bold">/</mi><mtext>kWh</mtext></mrow><mtext>  </mtext><mo>⟹</mo><mtext>  </mtext><mover accent="true"><mrow><mtext>AVU</mtext><mi mathvariant="normal">/</mi><mi mathvariant="normal">$</mi></mrow><mo stretchy="true">‾</mo></mover><mo>≈</mo><mrow><mn mathvariant="bold">11.90</mn><mtext> AVU / $</mtext></mrow></mrow><annotation encoding="application/x-tex">\\overline{\\$/\\text{kWh}} \\approx \\mathbf{\\$0.084 / \\text{kWh}} \\implies \\overline{\\text{AVU} / \\$} \\approx \\mathbf{11.90\\text{ AVU / \\$}} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.25em;"></span><span class="mord overline"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.95em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">$/</span><span class="mord text"><span class="mord">kWh</span></span></span></span><span style="top:-3.87em;"><span class="pstrut" style="height:3em;"></span><span class="overline-line" style="border-bottom-width:0.04em;"></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.25em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathbf">$0.084/</span><span class="mord text"><span class="mord">kWh</span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">⟹</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.25em;"></span><span class="mord overline"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.95em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord text"><span class="mord">AVU</span></span><span class="mord">/$</span></span></span><span style="top:-3.87em;"><span class="pstrut" style="height:3em;"></span><span class="overline-line" style="border-bottom-width:0.04em;"></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.25em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathbf">11.90</span><span class="mord text"><span class="mord"> AVU / $</span></span></span></span></span></span></span></div><p>This matches the <strong>US Energy Information Administration (EIA) National Industrial Average</strong> (<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi mathvariant="normal">$</mi><mn>0.082</mn><mi mathvariant="normal">/</mi><mtext>kWh</mtext></mrow><annotation encoding="application/x-tex">\\$0.082/\\text{kWh}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">$0.082/</span><span class="mord text"><span class="mord">kWh</span></span></span></span></span> or <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>12.2</mn><mtext> kWh/$</mtext></mrow><annotation encoding="application/x-tex">12.2\\text{ kWh/\\$}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">12.2</span><span class="mord text"><span class="mord"> kWh/$</span></span></span></span></span>).</p><hr><h2 id="how-the-app-computes-avu-values" tabindex="-1">How the app computes AVU values <a class="header-anchor" href="#how-the-app-computes-avu-values" aria-label="Permalink to &quot;How the app computes AVU values&quot;">​</a></h2><p>AVU is a unit of account, not a coin or token: 1 AVU = 1 kWh. Two readings say how many kWh a dollar is worth, and the app shows both.</p><p><strong>AVU_hash</strong> is read off proof-of-work mining and needs no electricity price. For each entry <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>c</mi></mrow><annotation encoding="application/x-tex">c</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">c</span></span></span></span> of a basket of mined coins at time <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>t</mi></mrow><annotation encoding="application/x-tex">t</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord mathnormal">t</span></span></span></span>, the dollars one kWh of mining earns are</p><div class="katex-display"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mi mathvariant="normal">$</mi><mi mathvariant="normal">/</mi><msub><mtext>kWh</mtext><mi>c</mi></msub><mo stretchy="false">(</mo><mi>t</mi><mo stretchy="false">)</mo><mo>=</mo><msub><mtext>price</mtext><mi>c</mi></msub><mo stretchy="false">(</mo><mi>t</mi><mo stretchy="false">)</mo><mrow><mo fence="true">[</mo><mstyle scriptlevel="0" displaystyle="false"><mfrac><mi mathvariant="normal">$</mi><mtext>coin</mtext></mfrac></mstyle><mo fence="true">]</mo></mrow><mo>×</mo><msub><mtext>subsidy</mtext><mi>c</mi></msub><mo stretchy="false">(</mo><mi>t</mi><mo stretchy="false">)</mo><mrow><mo fence="true">[</mo><mstyle scriptlevel="0" displaystyle="false"><mfrac><mtext>coins</mtext><mtext>block</mtext></mfrac></mstyle><mo fence="true">]</mo></mrow><mo>÷</mo><msub><mtext>hashes per block</mtext><mi>c</mi></msub><mo stretchy="false">(</mo><mi>t</mi><mo stretchy="false">)</mo><mo>×</mo><msub><mtext>efficiency</mtext><mi>c</mi></msub><mo stretchy="false">(</mo><mi>t</mi><mo stretchy="false">)</mo><mrow><mo fence="true">[</mo><mstyle scriptlevel="0" displaystyle="false"><mfrac><mtext>hashes</mtext><mtext>kWh</mtext></mfrac></mstyle><mo fence="true">]</mo></mrow></mrow><annotation encoding="application/x-tex">\\$/\\text{kWh}_c(t) = \\text{price}_c(t)\\left[\\tfrac{\\$}{\\text{coin}}\\right] \\times \\text{subsidy}_c(t)\\left[\\tfrac{\\text{coins}}{\\text{block}}\\right] \\div \\text{hashes per block}_c(t) \\times \\text{efficiency}_c(t)\\left[\\tfrac{\\text{hashes}}{\\text{kWh}}\\right] </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">$/</span><span class="mord"><span class="mord text"><span class="mord">kWh</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">c</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal">t</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.8em;vertical-align:-0.65em;"></span><span class="mord"><span class="mord text"><span class="mord">price</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.0573em;"><span style="top:-2.4559em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">c</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2441em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal">t</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner"><span class="mopen delimcenter" style="top:0em;"><span class="delimsizing size2">[</span></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.919em;"><span style="top:-2.655em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">coin</span></span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.394em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">$</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.345em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mclose delimcenter" style="top:0em;"><span class="delimsizing size2">]</span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.2115em;vertical-align:-0.35em;"></span><span class="mord"><span class="mord text"><span class="mord">subsidy</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.0573em;"><span style="top:-2.4559em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">c</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2441em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal">t</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner"><span class="mopen delimcenter" style="top:0em;"><span class="delimsizing size1">[</span></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8615em;"><span style="top:-2.655em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">block</span></span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.394em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">coins</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.345em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mclose delimcenter" style="top:0em;"><span class="delimsizing size1">]</span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">÷</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord text"><span class="mord">hashes per block</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.0573em;"><span style="top:-2.4559em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">c</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2441em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal">t</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.2301em;vertical-align:-0.35em;"></span><span class="mord"><span class="mord text"><span class="mord">efficiency</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.0573em;"><span style="top:-2.4559em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">c</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2441em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal">t</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner"><span class="mopen delimcenter" style="top:0em;"><span class="delimsizing size1">[</span></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8801em;"><span style="top:-2.655em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">kWh</span></span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.394em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">hashes</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.345em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mclose delimcenter" style="top:0em;"><span class="delimsizing size1">]</span></span></span></span></span></span></span></div><p>and AVU_hash is the weighted average of the inverses, in kWh per dollar:</p><div class="katex-display"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mtext>AVU_hash</mtext><mo stretchy="false">(</mo><mi>t</mi><mo stretchy="false">)</mo><mo>=</mo><munder><mo>∑</mo><mi>c</mi></munder><msub><mi>w</mi><mi>c</mi></msub><mo stretchy="false">(</mo><mi>t</mi><mo stretchy="false">)</mo><mo>×</mo><msup><mrow><mo fence="true">(</mo><mi mathvariant="normal">$</mi><mi mathvariant="normal">/</mi><msub><mtext>kWh</mtext><mi>c</mi></msub><mo stretchy="false">(</mo><mi>t</mi><mo stretchy="false">)</mo><mo fence="true">)</mo></mrow><mrow><mo>−</mo><mn>1</mn></mrow></msup></mrow><annotation encoding="application/x-tex">\\text{AVU\\_hash}(t) = \\sum_c w_c(t) \\times \\left(\\$/\\text{kWh}_c(t)\\right)^{-1} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.06em;vertical-align:-0.31em;"></span><span class="mord text"><span class="mord">AVU_hash</span></span><span class="mopen">(</span><span class="mord mathnormal">t</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.3em;vertical-align:-1.25em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.05em;"><span style="top:-1.9em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">c</span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">∑</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.25em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0269em;">w</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0269em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">c</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal">t</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.204em;vertical-align:-0.25em;"></span><span class="minner"><span class="minner"><span class="mopen delimcenter" style="top:0em;">(</span><span class="mord">$/</span><span class="mord"><span class="mord text"><span class="mord">kWh</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">c</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal">t</span><span class="mclose">)</span><span class="mclose delimcenter" style="top:0em;">)</span></span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.954em;"><span style="top:-3.2029em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mtight">1</span></span></span></span></span></span></span></span></span></span></span></span></span></div><p>The AVU value of any coin is <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mtext>price</mtext><mo stretchy="false">(</mo><mi>t</mi><mo stretchy="false">)</mo><mo>×</mo><mtext>AVU_hash</mtext><mo stretchy="false">(</mo><mi>t</mi><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">\\text{price}(t) \\times \\text{AVU\\_hash}(t)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord text"><span class="mord">price</span></span><span class="mopen">(</span><span class="mord mathnormal">t</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.06em;vertical-align:-0.31em;"></span><span class="mord text"><span class="mord">AVU_hash</span></span><span class="mopen">(</span><span class="mord mathnormal">t</span><span class="mclose">)</span></span></span></span>: kWh per coin. That is every &quot;≈ N AVU&quot; figure in the app.</p><p>Weights (<code>basketWeights</code>). Each entry&#39;s weight is its share of the basket&#39;s total market capitalisation. If Bitcoin&#39;s share is above 60% it is set to 60% and the other 40% is divided among the other entries in proportion to their market capitalisations. Weights sum to 1. Bitcoin alone has weight 1.</p><p>The basket has five entries: BTC, BCH, XEC, merge-mined LTC+DOGE, and XMR. Merge-mined chains are one entry: one hash earns on both, so their pay per hash is summed (each: price × block reward ÷ (difficulty × 2³²)), the energy is counted once, and the entry&#39;s weight is the sum of the two market capitalisations. Monero&#39;s expected hashes per block is its difficulty itself (no 2³²). An entry whose inputs are not all known at <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>t</mi></mrow><annotation encoding="application/x-tex">t</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord mathnormal">t</span></span></span></span> is left out and the weights are taken over the rest; the app shows how many entries were used and why each other one was not. With none, there is no AVU_hash and no AVU value: nothing falls back to a fixed rate.</p><p><strong>AVU_spot</strong> is the inverse of the feed&#39;s aggregate wholesale electricity price at <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>t</mi></mrow><annotation encoding="application/x-tex">t</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord mathnormal">t</span></span></span></span>. The feed builds that price: per region the mean of its daily day-ahead prices in the 30 days ending at each day (a region with fewer than 10 of them is left out), then the regions averaged equally. Prices are averaged first and the mean inverted; a value that is not positive has no AVU_spot.</p><h3 id="the-oracle-feed" tabindex="-1">The oracle feed <a class="header-anchor" href="#the-oracle-feed" aria-label="Permalink to &quot;The oracle feed&quot;">​</a></h3><p>The relay is the oracle. The app asks its relay for one normalised feed (<code>docs/protocol/oracle/README.md</code>) and knows nothing about any provider. Every input above is a series in that feed, read by one lookup: the latest point at or before a time, never interpolated, never extended backwards (<code>packages/price-feeds/src/timeseries.ts</code>). Today&#39;s figures and every point of a chart are the same functions (<code>avuHashAt</code>, <code>avuSpotAt</code> in <code>packages/wallet/oracle/energy-basket.ts</code>) evaluated at different times.</p><p>The app shell holds the feed for the life of the app (<code>useAppOracleFeed</code>): the latest answer is asked for every 10 minutes while the window is visible, appended to the local series in LevelDB, and the AVU rate of every asset is computed from it once (<code>current</code> in <code>app/src/stores/oracle.ts</code>). Everything on screen reads that. The Parity chart, while on screen, asks for a range only for the stretches the local series lack.</p><p>Until relays serve the route (a 404), the app fills the same contract itself with <code>packages/price-feeds/src/temporary-direct-feed.ts</code>: prices are the median of the public providers that answer, chain statistics are Blockchair&#39;s <code>/stats</code> (hourly), and history is the bundled files below. That file and what only it uses are to be deleted when the relay serves the feed; the bundled files then become the relay&#39;s seed data.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Series</th><th style="text-align:left;">Bundled history (<code>packages/price-feeds/src/historical</code>)</th><th style="text-align:left;">Built by</th></tr></thead><tbody><tr><td style="text-align:left;">Bitcoin price, difficulty, subsidy, supply; SHA-256 efficiency (Cambridge CBECI fleet estimate)</td><td style="text-align:left;"><code>btc-mining-monthly.json</code>, monthly from 2010</td><td style="text-align:left;"><code>scripts/build-btc-mining-history.py</code></td></tr><tr><td style="text-align:left;">Litecoin, Dogecoin, Bitcoin Cash, eCash, Monero: price, difficulty, subsidy, supply</td><td style="text-align:left;"><code>mined-chains-monthly.json</code>, monthly</td><td style="text-align:left;"><code>scripts/build-mined-chains-history.py</code></td></tr><tr><td style="text-align:left;">scrypt and RandomX efficiency (best hardware on sale, dated steps); eCash miner share (dated steps read from coinbases)</td><td style="text-align:left;"><code>curated-steps.json</code>, written by hand, every step cited</td><td style="text-align:left;">—</td></tr><tr><td style="text-align:left;">Wholesale electricity, daily, per region and aggregated</td><td style="text-align:left;"><code>wholesale-electricity-daily.json</code></td><td style="text-align:left;"><code>scripts/build-wholesale-electricity.py</code></td></tr><tr><td style="text-align:left;">Gold, yearly (World Bank)</td><td style="text-align:left;"><code>us-electricity-gold.json</code></td><td style="text-align:left;"><code>scripts/build-historical.py</code></td></tr></tbody></table><p>Each script&#39;s header names its source URLs and the exact command. Every file carries its retrieval date.</p><p>The efficiency series are the inputs that are neither a chain reading nor a market price. SHA-256 is Cambridge&#39;s model of the machines actually running (its best guess assumes miners pay 0.05 USD/kWh when deciding which machines are still profitable). Scrypt and RandomX are the most efficient machine on sale at each date: a frontier, which is more efficient than a fleet, so those two entries&#39; pay per kWh reads higher than a fleet estimate would give. The RandomX steps before the first ASIC (September 2023) are desktop processors rated at their package power limit and are marked as estimates.</p><p>Staleness. A price that has missed two refreshes, or an AVU_hash whose oldest market or chain reading is over two hours old (including a bundled monthly value standing in where nothing newer was received), is shown with its age. There are no stand-in prices: a coin the feed has no price for has no AVU value. Test-network coins are valued at their main network&#39;s price and marked &quot;testnet&quot;. No dollar figure is shown anywhere in the app.</p><p>The tables in the sections above (per-network rates, the $0.084 &quot;composite&quot;, the grid comparison, the purchasing-power eras) are illustrations written with the original text. No code reads them and their figures were not computed from sources.</p><hr><h2 id="protocol-architecture" tabindex="-1">Protocol Architecture <a class="header-anchor" href="#protocol-architecture" aria-label="Permalink to &quot;Protocol Architecture&quot;">​</a></h2><ol><li><strong><code>@frank/price-feeds</code></strong>: the feed contract&#39;s types, parser and fetch (<code>feed.ts</code>), the timeseries lookup (<code>timeseries.ts</code>), and the temporary direct adapter.</li><li><strong><code>@frank/wallet/oracle</code></strong>: pure TypeScript, no Vue/DOM. <code>avuHashAt</code>, <code>avuSpotAt</code>, <code>computeOracleRates</code> (every asset&#39;s AVU rate at a time), <code>convertRawToAvu</code>.</li><li><strong><code>useOracleStore()</code> (<code>app/src/stores/oracle.ts</code>)</strong>: the local series, the cached rates, and the one display helper <code>formatAvuAmount(asset, rawAmount)</code>: an AVU string or nothing.</li></ol>',72)])])}const g=a(p,[["render",l]]);export{d as __pageData,g as default};
